// ── ARRAIAL D'AJUDA PSYCHEDELIC RAVE — Dark Psy Trance Party ──
// mt, w1, w2, w3, w, h, bY, bCol, wc, ol, isN, sc — runtime
// Note: This scene is always night mode (psychedelic dark party)

// Psychedelic nebula sky gradient
svg += `<defs>
  <linearGradient id="lg-arraial-rave" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${sc.sky1}"/>
    <stop offset="50%" stop-color="#330033"/>
    <stop offset="100%" stop-color="${sc.sky2}"/>
  </linearGradient>
  <radialGradient id="rg-psy-center" cx="0.5" cy="0.3" r="0.8">
    <stop offset="0%" stop-color="#FF00FF" stop-opacity="0.3"/>
    <stop offset="100%" stop-color="#000000" stop-opacity="0"/>
  </radialGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-arraial-rave)"/>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#rg-psy-center)" opacity="${0.3 + w1 * 0.2}"/>`;

// Animated nebula/stars (psychedelic patterns)
for (let i = 0; i < 25; i++) {
  const starX = (i * 41) % (w - 30) + 15;
  const starY = (i * 29) % (h * 0.6) + 20;
  const pulse = Math.sin(mt * 4 + i * 0.5) * 0.5 + 0.5;
  const size = 1 + pulse * 2;
  const hueRot = (i * 36 + mt * 50) % 360;

  svg += `<circle cx="${starX}" cy="${starY}" r="${size}" 
           fill="hsl(${hueRot}, 100%, 70%)" opacity="${0.3 + pulse * 0.4}"/>`;

  // Star trails
  svg += `<path d="M ${starX} ${starY} 
           q ${Math.sin(mt + i) * 20} ${Math.cos(mt + i) * 15} 0 0" 
           fill="none" stroke="hsl(${hueRot}, 100%, 60%)" 
           stroke-width="1" opacity="0.2" stroke-dasharray="3,3"/>`;
}

// Ocean (dark with psychedelic reflections)
const oceanY = h * 0.66;
svg += `<rect x="0" y="${oceanY}" width="${w}" height="${h - oceanY}" fill="#000022"/>`;

// Psychedelic ocean waves
for (let i = 0; i < 8; i++) {
  const waveY = oceanY + i * 4 + Math.sin(mt * 3 + i * 1.2) * 3;
  const hue = (mt * 100 + i * 40) % 360;
  const waveHeight = 2 + w2 * 3;

  svg += `<path d="M0 ${waveY} 
           Q ${w * 0.3} ${waveY + waveHeight} ${w * 0.6} ${waveY} 
           T ${w} ${waveY}" 
           fill="none" stroke="hsl(${hue}, 100%, 60%)" 
           stroke-opacity="0.6" stroke-width="2"/>`;
}

// Beach dance floor (pulsating grid)
const danceFloorY = oceanY - 40;
svg += `<rect x="0" y="${danceFloorY}" width="${w}" height="40" fill="#111111"/>`;

// Dance floor grid pattern
for (let i = 0; i < 10; i++) {
  for (let j = 0; j < 4; j++) {
    const cellX = i * (w / 10);
    const cellY = danceFloorY + j * 10;
    const pulse = Math.sin(mt * 5 + i * 0.7 + j * 1.3) * 0.5 + 0.5;
    const hue = (mt * 80 + i * 30 + j * 15) % 360;

    svg += `<rect x="${cellX}" y="${cellY}" width="${w / 10}" height="10" 
             fill="hsl(${hue}, 100%, ${30 + pulse * 40}%)" opacity="${0.3 + pulse * 0.5}"/>`;
  }
}

// Silhouette cliffs (Pitinga & Mucugê as dark shapes)
const cliffLeftX = w * 0.15;
const cliffHeight = 70;
svg += `<path d="M ${cliffLeftX - 50} ${oceanY} 
           Q ${cliffLeftX} ${oceanY - cliffHeight} ${cliffLeftX + 50} ${oceanY} 
           Z" fill="${sc.bld}"/>`;

const cliffRightX = w * 0.75;
const cliffHeightRight = 55;
svg += `<path d="M ${cliffRightX - 40} ${oceanY} 
           Q ${cliffRightX} ${oceanY - cliffHeightRight} ${cliffRightX + 40} ${oceanY} 
           Z" fill="${sc.bld}"/>`;

// Psychedelic projections on cliffs
for (let i = 0; i < 5; i++) {
  const projX = cliffLeftX - 30 + i * 20;
  const projY = oceanY - cliffHeight + 20;
  const projSize = 15 + Math.sin(mt * 2 + i) * 5;
  const hue = (mt * 60 + i * 72) % 360;

  // Mandala/fractal patterns
  for (let r = 0; r < 3; r++) {
    const radius = projSize * (0.3 + r * 0.3);
    const rotation = mt * 20 + i * 15;

    svg += `<circle cx="${projX}" cy="${projY}" r="${radius}" 
             fill="none" stroke="hsl(${hue}, 100%, 70%)" 
             stroke-width="1" opacity="0.4" 
             transform="rotate(${rotation}, ${projX}, ${projY})"/>`;
  }
}

// Laser beams from cliffs
for (let i = 0; i < 3; i++) {
  const laserX = cliffLeftX - 20 + i * 30;
  const laserY = oceanY - cliffHeight + 10;
  const laserAngle = Math.sin(mt * 1.5 + i) * 0.5 - 0.5;
  const laserLength = 200 + Math.sin(mt * 2 + i) * 50;
  const laserEndX = laserX + Math.cos(laserAngle) * laserLength;
  const laserEndY = laserY + Math.sin(laserAngle) * laserLength;
  const hue = (mt * 100 + i * 120) % 360;

  svg += `<line x1="${laserX}" y1="${laserY}" 
           x2="${laserEndX}" y2="${laserEndY}" 
           stroke="hsl(${hue}, 100%, 70%)" stroke-width="2" 
           opacity="0.7" stroke-dasharray="10,5">
          <animate attributeName="opacity" values="0.3;0.7;0.3" 
                   dur="0.5s" repeatCount="indefinite"/>
        </line>`;
}

// DJ booth on the beach
const djX = w * 0.5;
const djY = danceFloorY - 30;
svg += `<rect x="${djX - 40}" y="${djY}" width="80" height="30" fill="#000000" stroke="#FF00FF" stroke-width="2"/>`;
svg += `<rect x="${djX - 35}" y="${djY + 5}" width="70" height="20" fill="#222222"/>`;

// DJ equipment (animated lights)
for (let i = 0; i < 6; i++) {
  const lightX = djX - 30 + i * 12;
  const lightY = djY + 10;
  const pulse = Math.sin(mt * 8 + i * 0.9) * 0.5 + 0.5;
  const hue = (mt * 120 + i * 60) % 360;

  svg += `<circle cx="${lightX}" cy="${lightY}" r="${3 + pulse}" 
           fill="hsl(${hue}, 100%, 70%)" opacity="0.8"/>`;
}

// Dancing silhouettes (psychedelic ravers)
for (let i = 0; i < 8; i++) {
  const dancerX = 30 + i * (w / 9);
  const dancerY = danceFloorY + 20;
  const danceMove = Math.sin(mt * 4 + i * 1.2) * 8;
  const hue = (mt * 40 + i * 45) % 360;

  // Body
  svg += `<ellipse cx="${dancerX}" cy="${dancerY - 15 - danceMove}" rx="6" ry="8" fill="hsl(${hue}, 80%, 30%)"/>`;

  // Head
  svg += `<circle cx="${dancerX}" cy="${dancerY - 25 - danceMove}" r="5" fill="hsl(${hue}, 80%, 30%)"/>`;

  // Arms
  const armAngle = Math.sin(mt * 3 + i) * 0.8;
  const leftArmX = dancerX - Math.cos(armAngle) * 12;
  const leftArmY = dancerY - 20 - danceMove + Math.sin(armAngle) * 12;
  const rightArmX = dancerX + Math.cos(armAngle) * 12;
  const rightArmY = dancerY - 20 - danceMove - Math.sin(armAngle) * 12;

  svg += `<line x1="${dancerX}" y1="${dancerY - 20 - danceMove}" 
           x2="${leftArmX}" y2="${leftArmY}" 
           stroke="hsl(${hue}, 80%, 30%)" stroke-width="3" stroke-linecap="round"/>`;

  svg += `<line x1="${dancerX}" y1="${dancerY - 20 - danceMove}" 
           x2="${rightArmX}" y2="${rightArmY}" 
           stroke="hsl(${hue}, 80%, 30%)" stroke-width="3" stroke-linecap="round"/>`;
}

// Sound waves emanating from DJ booth
for (let i = 0; i < 5; i++) {
  const waveRadius = 50 + i * 30 + Math.sin(mt * 3) * 20;
  const hue = (mt * 80 + i * 40) % 360;
  const opacity = 0.6 - i * 0.1;

  svg += `<circle cx="${djX}" cy="${djY + 15}" r="${waveRadius}" 
           fill="none" stroke="hsl(${hue}, 100%, 60%)" 
           stroke-width="2" opacity="${opacity}" stroke-dasharray="5,5"/>`;
}

// Psychedelic moon (trippy version)
const moonX = w * 0.85;
const moonY = h * 0.22;
const moonPulse = Math.sin(mt * 2) * 0.5 + 0.5;

// Main moon
svg += `<circle cx="${moonX}" cy="${moonY}" r="25" fill="#FF00FF" opacity="0.7">
        <animate attributeName="r" values="22;28;22" dur="3s" repeatCount="indefinite"/>
       </circle>`;

// Moon mandala patterns
for (let i = 0; i < 4; i++) {
  const ringRadius = 35 + i * 15;
  const rotation = mt * 20 + i * 45;
  const hue = (mt * 50 + i * 90) % 360;

  svg += `<circle cx="${moonX}" cy="${moonY}" r="${ringRadius}" 
           fill="none" stroke="hsl(${hue}, 100%, 60%)" 
           stroke-width="1" opacity="0.4" stroke-dasharray="3,3"
           transform="rotate(${rotation}, ${moonX}, ${moonY})"/>`;
}

// Floating fractal patterns in the sky
for (let i = 0; i < 7; i++) {
  const fractalX = (w1 * w * 0.8 + i * 60) % (w * 0.8) + 50;
  const fractalY = h * 0.3 + Math.sin(mt * 1.5 + i) * 30;
  const fractalSize = 15 + Math.sin(mt * 2 + i) * 8;
  const hue = (mt * 90 + i * 51) % 360;
  const rotation = mt * 30 + i * 25;

  // Create a simple fractal/mandala
  for (let j = 0; j < 6; j++) {
    const angle = (j / 6) * Math.PI * 2;
    const petalLength = fractalSize * (0.5 + Math.sin(mt + j) * 0.3);
    const petalX = fractalX + Math.cos(angle) * petalLength;
    const petalY = fractalY + Math.sin(angle) * petalLength;

    svg += `<line x1="${fractalX}" y1="${fractalY}" 
             x2="${petalX}" y2="${petalY}" 
             stroke="hsl(${hue}, 100%, 70%)" stroke-width="1.5" 
             opacity="0.6" stroke-linecap="round"/>`;
  }
}

// Smoke/mist effect from the dance floor
for (let i = 0; i < 5; i++) {
  const smokeX = 100 + i * 80 + Math.sin(mt * 0.5 + i) * 40;
  const smokeY = danceFloorY - 20 - Math.sin(mt * 1 + i) * 15;
  const smokeSize = 20 + Math.sin(mt * 1.5 + i) * 10;
  const hue = (mt * 30 + i * 20) % 360;

  svg += `<ellipse cx="${smokeX}" cy="${smokeY}" 
           rx="${smokeSize}" ry="${smokeSize * 0.7}" 
           fill="hsl(${hue}, 50%, 40%)" opacity="0.2">
          <animate attributeName="cy" values="${smokeY};${smokeY - 30};${smokeY}" 
                   dur="4s" repeatCount="indefinite"/>
          <animate attributeName="opacity" values="0.1;0.3;0.1" 
                   dur="3s" repeatCount="indefinite"/>
        </ellipse>`;
}
